'use strict';

// MODULES //

var erfcx = require( '@stdlib/math/base/special/erfcx' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var sqrt = require( '@stdlib/math/base/special/sqrt' );
var erfc = require( '@stdlib/math/base/special/erfc' );
var exp = require( '@stdlib/math/base/special/exp' );
var ln = require( '@stdlib/math/base/special/ln' );
var PINF = require( '@stdlib/constants/float64/pinf' );
var NINF = require( '@stdlib/constants/float64/ninf' );


// MAIN //

/**
* Evaluates the natural logarithm of the cumulative distribution function (CDF) for a Wald distribution with mean `mu` and shape parameter `lambda` at a value `x`.
*
* @param {number} x - input value
* @param {PositiveNumber} mu - mean
* @param {NonNegativeNumber} lambda - shape parameter
* @returns {number} evaluated logCDF
*
* @example
* var y = logcdf( 2.0, 1.0, 1.0 );
* // returns ~-0.122
*
* @example
* var y = logcdf( 0.5, 2.0, 3.0 );
* // returns ~-2.897
*
* @example
* var y = logcdf( NaN, 1.0, 1.0 );
* // returns NaN
*
* @example
* var y = logcdf( 1.0, NaN, 1.0 );
* // returns NaN
*
* @example
* var y = logcdf( 1.0, 1.0, NaN );
* // returns NaN
*
* @example
* // Non-positive mean:
* var y = logcdf( 2.0, 0.0, 1.0 );
* // returns NaN
*
* @example
* // Negative shape parameter:
* var y = logcdf( 2.0, 1.0, -1.0 );
* // returns NaN
*
* @example
* // Zero shape parameter (degenerate distribution):
* var y = logcdf( 1.0, 1.0, 0.0 );
* // returns 0.0
*
* @example
* var y = logcdf( 0.0, 1.0, 1.0 );
* // returns -Infinity
*/
function logcdf( x, mu, lambda ) {
	var t1;
	var t2;
	var a;
	var b;
	var z;

	if (
		isnan( x ) ||
		isnan( mu ) ||
		isnan( lambda ) ||
		mu <= 0.0 ||
		lambda < 0.0
	) {
		return NaN;
	}
	if ( lambda === 0.0 ) {
		return ( x < mu ) ? NINF : 0.0;
	}
	if ( x <= 0.0 ) {
		return NINF;
	}
	if ( x === PINF ) {
		return 0.0;
	}
	z = sqrt( lambda / x );
	a = ( z * ( ( x / mu ) - 1.0 ) ) / sqrt( 2.0 );
	b = ( z * ( ( x / mu ) + 1.0 ) ) / sqrt( 2.0 );

	// Φ(a) = 0.5 * erfc( -a / sqrt( 2 ) )
	t1 = 0.5 * erfc( -a );

	// exp( 2λ/μ ) * erfc( b ) = erfcx( b ) * exp( -a² ), as b² - a² = 2λ/μ; computing via `erfcx` avoids overflow of the exponential term for large `λ/μ`:
	t2 = 0.5 * erfcx( b ) * exp( -a * a );
	return ln( t1 + t2 );
}


// EXPORTS //

module.exports = logcdf;
